  1	import { useEffect, useState } from 'react'
  2	import { createRoot } from 'react-dom/client'
  3	import { Workbench } from '@frade/ui-workspace'
  4	import { ThemeControllerContext } from '@frade/ui-workspace/design/theme'
  5	import { bootstrapPresentation } from './presentation-bootstrap'
  6	import type { WorkbenchClient } from '@frade/repository-api/workbench'
  7	import type { DesktopApi, Health, PresentationApi } from '@frade/runtime-contracts'
  8	import './style.css'
  9	import '@frade/ui-workspace/styles.css'
 10	import '@frade/ui-workspace/design/tokens.css'
 11	import '@frade/ui-workspace/design/theme/theme-consumers.css'
 12	const presentation = bootstrapPresentation(window.fradePresentation, document.documentElement)
 13	declare global {
 14	  interface Window {
 15	    fradePresentation: PresentationApi
 16	    frade: DesktopApi
 17	    fradeWorkbench: WorkbenchClient & { onCloseRequested: (listener: () => void) => () => void }
 18	  }
 19	}
 20	function App() {
 21	  const [health, setHealth] = useState<Health>({ state: 'starting', sequence: 0 })
 22	  useEffect(() => {
 23	    let active = true
 24	    const update = (next: Health) => {
 25	      if (active) setHealth((previous) => (next.sequence >= previous.sequence ? next : previous))
 26	    }
 27	    const off = window.frade.events.subscribe(update)
 28	    void window.frade.runtime
 29	      .getHealth()
 30	      .then(update)
 31	      .catch(() => update({ state: 'unavailable', sequence: 0 }))
 32	    return () => {
 33	      active = false
 34	      off()
 35	    }
 36	  }, [])
 37	  return <Workbench client={window.fradeWorkbench} health={health.state} />
 38	}
 39	createRoot(document.getElementById('root')!).render(
 40	  <ThemeControllerContext.Provider value={presentation.controller}>
 41	    <App />
 42	  </ThemeControllerContext.Provider>,
 43	)
 44	void presentation.ready().catch((error) => console.error('Presentation startup failed', error))
 45	window.addEventListener('pagehide', () => presentation.dispose(), { once: true })
375	      }
376	    },
377	  }
378	  return store
379	}
380	export function createPresentationVisibility(
381	  boot: PresentationBoot,
382	  show: () => void,
383	  failure: (reason: string) => void,
384	): {
385	  nativeReady(): void
386	  presentationReady(bootRevision: number, rootRevision: number): void
387	  dispose(): void
388	} {
389	  let native = false,
390	    presentation = false,
391	    closed = false,
392	    shown = false
393	  const timer = setTimeout(() => {
394	    if (!shown && !closed) {
395	      closed = true
396	      failure('Presentation bootstrap handshake timeout (5000ms)')
397	    }
398	  }, 5000)
399	  const reveal = () => {
400	    if (native && presentation && !closed && !shown) {
401	      shown = true
402	      clearTimeout(timer)
403	      show()
404	    }
405	  }
406	  return {
407	    nativeReady: () => {
408	      native = true
409	      reveal()
410	    },
411	    presentationReady: (bootRevision, rootRevision) => {
412	      if (bootRevision !== boot.bootRevision || rootRevision !== boot.snapshot.revision) return
413	      presentation = true
414	      reveal()
415	    },
416	    dispose: () => {
417	      closed = true
418	      clearTimeout(timer)
419	    },
420	  }
421	}
